using System.Text.Json;
namespace Reforged.Server;
public enum RuntimeOfflineMessageKind { PlayerMail, SystemMail, QuestMail, AdministrativeMail, OfflineTell, Note, Bulletin, Announcement }
public enum RuntimeOfflineMessageState { Queued, Delivered, Read, Deleted, Expired, Rejected }
public sealed record RuntimeOfflineAttachment(string Kind,string AssetId,long Amount);
public sealed record RuntimeOfflineMessagePolicy(int MaximumSubjectLength,int MaximumBodyLength,int MaximumInboxMessages,TimeSpan DefaultLifetime,bool AllowItemAttachments,bool AllowCurrencyAttachments,bool EnablePlayerMail,bool EnableOfflineTells);
public sealed record RuntimeOfflineMessageEnvelope(string MessageId,RuntimeOfflineMessageKind Kind,string? SenderCharacterId,string RecipientCharacterId,string Subject,string Body,IReadOnlyList<RuntimeOfflineAttachment> Attachments,DateTimeOffset CreatedUtc,DateTimeOffset ExpiresUtc,RuntimeOfflineMessageState State,long Revision);
public sealed record RuntimeOfflineOwnerRequest(string Owner,string Operation,string CharacterId,string AssetId,long Amount,string CorrelationId);
public sealed record RuntimeOfflineMessageResult(bool Accepted,string Code,RuntimeOfflineMessageState State,RuntimeOfflineMessageEnvelope? Message,IReadOnlyList<RuntimeOfflineOwnerRequest> OwnerRequests);
public sealed class RuntimeOfflineMessagingService
{
 private const int SchemaVersion=1; private readonly RuntimeOfflineMessagePolicy _policy; private readonly Dictionary<string,RuntimeOfflineMessageEnvelope> _messages=new(StringComparer.OrdinalIgnoreCase); private readonly string? _persistencePath;
 public RuntimeOfflineMessagingService(RuntimeOfflineMessagePolicy policy,string? persistencePath=null){if(policy.MaximumSubjectLength<=0||policy.MaximumBodyLength<=0||policy.MaximumInboxMessages<=0||policy.DefaultLifetime<=TimeSpan.Zero)throw new ArgumentException("invalid-offline-message-policy");_policy=policy;_persistencePath=persistencePath;Load();}
 public RuntimeOfflineMessageResult Queue(string id,RuntimeOfflineMessageKind kind,string? sender,string recipient,string subject,string body,IReadOnlyList<RuntimeOfflineAttachment> attachments,DateTimeOffset now,bool senderIsAdministrator=false)
 {
  if(string.IsNullOrWhiteSpace(id)||string.IsNullOrWhiteSpace(recipient))return Reject("invalid-message-identity"); if(_messages.ContainsKey(id))return Reject("duplicate-message");
  if(kind==RuntimeOfflineMessageKind.PlayerMail&&!_policy.EnablePlayerMail)return Reject("player-mail-disabled"); if(kind==RuntimeOfflineMessageKind.OfflineTell&&!_policy.EnableOfflineTells)return Reject("offline-tells-disabled");
  if(kind==RuntimeOfflineMessageKind.AdministrativeMail&&!senderIsAdministrator)return Reject("administrator-required"); if(subject.Length>_policy.MaximumSubjectLength||body.Length>_policy.MaximumBodyLength)return Reject("message-too-long");
  if(_messages.Values.Count(x=>x.RecipientCharacterId.Equals(recipient,StringComparison.OrdinalIgnoreCase)&&x.State is not RuntimeOfflineMessageState.Deleted and not RuntimeOfflineMessageState.Expired)>=_policy.MaximumInboxMessages)return Reject("recipient-mailbox-full");
  foreach(var a in attachments){if(string.IsNullOrWhiteSpace(a.Kind)||string.IsNullOrWhiteSpace(a.AssetId)||a.Amount<=0)return Reject("invalid-attachment");if(a.Kind.Equals("item",StringComparison.OrdinalIgnoreCase)&&!_policy.AllowItemAttachments)return Reject("item-attachments-disabled");if(a.Kind.Equals("currency",StringComparison.OrdinalIgnoreCase)&&!_policy.AllowCurrencyAttachments)return Reject("currency-attachments-disabled");if(!a.Kind.Equals("item",StringComparison.OrdinalIgnoreCase)&&!a.Kind.Equals("currency",StringComparison.OrdinalIgnoreCase))return Reject("unknown-attachment-kind");}
  var m=new RuntimeOfflineMessageEnvelope(id,kind,sender,recipient,subject,body,attachments,now,now+_policy.DefaultLifetime,RuntimeOfflineMessageState.Queued,1);_messages[id]=m;Save();return new(true,"queued",m.State,m,BuildOwnerRequests(m,"reserve-attachment"));
 }
 public RuntimeOfflineMessageResult Deliver(string id,string recipient,DateTimeOffset now){if(!_messages.TryGetValue(id,out var m))return Reject("unknown-message");if(!m.RecipientCharacterId.Equals(recipient,StringComparison.OrdinalIgnoreCase))return Reject("not-recipient");if(m.State!=RuntimeOfflineMessageState.Queued)return Reject("invalid-state");if(now>=m.ExpiresUtc){m=m with{State=RuntimeOfflineMessageState.Expired,Revision=m.Revision+1};_messages[id]=m;Save();return new(false,"message-expired",m.State,m,BuildOwnerRequests(m,"release-attachment"));}m=m with{State=RuntimeOfflineMessageState.Delivered,Revision=m.Revision+1};_messages[id]=m;Save();return new(true,"delivered",m.State,m,Array.Empty<RuntimeOfflineOwnerRequest>());}
 public RuntimeOfflineMessageResult MarkRead(string id,string recipient){if(!_messages.TryGetValue(id,out var m))return Reject("unknown-message");if(!m.RecipientCharacterId.Equals(recipient,StringComparison.OrdinalIgnoreCase))return Reject("not-recipient");if(m.State is not RuntimeOfflineMessageState.Delivered and not RuntimeOfflineMessageState.Read)return Reject("invalid-state");m=m with{State=RuntimeOfflineMessageState.Read,Revision=m.Revision+1};_messages[id]=m;Save();return new(true,"read",m.State,m,Array.Empty<RuntimeOfflineOwnerRequest>());}
 public RuntimeOfflineMessageResult Delete(string id,string actor,bool administrator=false){if(!_messages.TryGetValue(id,out var m))return Reject("unknown-message");if(!administrator&&!m.RecipientCharacterId.Equals(actor,StringComparison.OrdinalIgnoreCase)&&!string.Equals(m.SenderCharacterId,actor,StringComparison.OrdinalIgnoreCase))return Reject("not-authorized");if(m.State==RuntimeOfflineMessageState.Deleted)return Reject("already-deleted");m=m with{State=RuntimeOfflineMessageState.Deleted,Revision=m.Revision+1};_messages[id]=m;Save();return new(true,"deleted",m.State,m,BuildOwnerRequests(m,"release-attachment"));}
 public IReadOnlyList<RuntimeOfflineMessageResult> Expire(DateTimeOffset now){var results=new List<RuntimeOfflineMessageResult>();foreach(var id in _messages.Values.Where(x=>x.State is RuntimeOfflineMessageState.Queued or RuntimeOfflineMessageState.Delivered or RuntimeOfflineMessageState.Read).Where(x=>now>=x.ExpiresUtc).Select(x=>x.MessageId).ToArray()){var m=_messages[id] with{State=RuntimeOfflineMessageState.Expired,Revision=_messages[id].Revision+1};_messages[id]=m;results.Add(new(false,"message-expired",m.State,m,BuildOwnerRequests(m,"release-attachment")));}if(results.Count>0)Save();return results;}
 public IReadOnlyList<RuntimeOfflineMessageEnvelope> Inbox(string recipient)=>_messages.Values.Where(x=>x.RecipientCharacterId.Equals(recipient,StringComparison.OrdinalIgnoreCase)&&x.State is not RuntimeOfflineMessageState.Deleted and not RuntimeOfflineMessageState.Expired).OrderBy(x=>x.CreatedUtc).ThenBy(x=>x.MessageId,StringComparer.OrdinalIgnoreCase).ToArray();
 public IReadOnlyList<string> ValidateState()=>_messages.Values.Where(x=>string.IsNullOrWhiteSpace(x.MessageId)||string.IsNullOrWhiteSpace(x.RecipientCharacterId)||x.Revision<=0||x.ExpiresUtc<=x.CreatedUtc).Select(x=>"invalid-message:"+x.MessageId).ToArray();
 private static IReadOnlyList<RuntimeOfflineOwnerRequest> BuildOwnerRequests(RuntimeOfflineMessageEnvelope m,string op)=>m.Attachments.Select(a=>new RuntimeOfflineOwnerRequest(a.Kind.Equals("currency",StringComparison.OrdinalIgnoreCase)?"Economy":"CharacterInventory",op,m.SenderCharacterId??m.RecipientCharacterId,a.AssetId,a.Amount,m.MessageId)).ToArray();
 private void Save(){if(string.IsNullOrWhiteSpace(_persistencePath))return;var path=Path.GetFullPath(_persistencePath);Directory.CreateDirectory(Path.GetDirectoryName(path)!);var tmp=path+".tmp";File.WriteAllText(tmp,JsonSerializer.Serialize(new Snapshot(SchemaVersion,_messages.Values.ToArray()),new JsonSerializerOptions{WriteIndented=true}));File.Move(tmp,path,true);}
 private void Load(){if(string.IsNullOrWhiteSpace(_persistencePath)||!File.Exists(_persistencePath))return;try{var s=JsonSerializer.Deserialize<Snapshot>(File.ReadAllText(_persistencePath));if(s?.SchemaVersion!=SchemaVersion)return;foreach(var m in s.Messages)if(!string.IsNullOrWhiteSpace(m.MessageId)&&m.Revision>0)_messages[m.MessageId]=m;}catch{_messages.Clear();}}
 private sealed record Snapshot(int SchemaVersion,IReadOnlyList<RuntimeOfflineMessageEnvelope> Messages);
 private static RuntimeOfflineMessageResult Reject(string code)=>new(false,code,RuntimeOfflineMessageState.Rejected,null,Array.Empty<RuntimeOfflineOwnerRequest>());
}
